sys_variable_value.value:
(function execute(inputs, outputs) {
    var text = inputs.text_to_scan;
    
    var patterns = {
        "Credit Card": /\b(?:\d[ -]*?){13,16}\b/,
        "SSN": /\b\d{3}-\d{2}-\d{4}\b/
    };

    outputs.is_sensitive = false;
    outputs.detected_pattern_type = "None";

    for (var key in patterns) {
        if (patterns[key].test(text)) {
            outputs.is_sensitive = true;
            outputs.detected_pattern_type = key;
            break; 
        }
    }
})(inputs, outputs);

